def transform(grid):
    n = len(grid[0])
    center = grid[0].index(2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r <= center and abs(c - center) == r:
                out[r][c] = 2
            elif r >= 3 and abs(c - center) < r and (c - r - center) % 4 == 0:
                out[r][c] = 1
    return out
